request.code:
// Always answers "1 2", whatever the case. Right for one checker case and
// wrong for the other -- which is the point: the checker, not the bytes,
// decides.
#include <cstdio>

int main() {
  std::printf("1 2\n");
  return 0;
}

request.checker:
// A checker that dies by a signal. nsjail reports it as its own
// 128 + SIGSEGV = 139 status and exits normally, so this is the case that
// used to fall through to "rejected" and mass-misgrade a whole problem.
static int* volatile p = nullptr;

int main() {
  *p = 1;
  return 0;
}
